  const selection=this.host.querySelector('.trim-selection');selection.style.left=left+'%';selection.style.width=(right-left)+'%';this.host.querySelector('.before').style.width=left+'%';this.host.querySelector('.after').style.left=right+'%';this.host.querySelector('.after').style.width=(100-right)+'%';this.host.querySelector('.trim-start').textContent=samplerSeconds(this.start);this.host.querySelector('.trim-end').textContent=samplerSeconds(this.end);this.host.querySelector('.trim-length').textContent=this.duration?samplerSeconds(this.end-this.start)+' selected'+(this.end-this.start>120?' · max 2 minutes':''):'Choose a source';this.host.classList.toggle('trim-too-long',this.end-this.start>120);
